@push('scripts')<script>document.querySelectorAll('[data-platform-toggle]').forEach(box=>box.addEventListener('change',()=>{const panel=document.querySelector(`[data-account-panel="${box.dataset.platformToggle}"]`);panel.classList.toggle('hidden',!box.checked);panel.querySelector('select').disabled=!box.checked;}));document.querySelectorAll('.status-select').forEach(el=>el.addEventListener('change',async()=>{const old=el.dataset.current;const r=await fetch(el.dataset.url,{method:'PATCH',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify({status:el.value})});if(!r.ok){el.value=old;alert((await r.json()).message||'Status change denied');}else{el.dataset.current=el.value;alert('Status updated successfully');}}));</script>@endpush
